import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { createScene, type PrintScene } from './scene';
import { directScene } from './director';

let scene: PrintScene | null = null;
let root: HTMLElement | null = null;
let stateNodes: HTMLElement[] = [];

const states = [
  { id: 'paper-ready', at: 0, label: '和纸就位' },
  { id: 'pressure-trace', at: .2, label: '木纹压痕' },
  { id: 'indigo-layer', at: .46, label: '靛蓝落版' },
  { id: 'vermilion-register', at: .72, label: '朱红套色' },
  { id: 'finished-imprint', at: 1, label: '作品完成' }
] as const;

function buildPage(container: HTMLElement): HTMLElement {
  const page = document.createElement('main');
  page.className = 'print-page';
  page.innerHTML = `
    <nav class="print-nav" aria-label="页面导航">
      <a class="print-mark" href="#paper-ready">日光套印所</a>
      <div class="state-meter" aria-label="当前工序">
        ${states.map((state, index) => `<span data-state="${state.id}"><b>${String(index + 1).padStart(2, '0')}</b>${state.label}</span>`).join('')}
      </div>
      <a href="#finished-imprint">预约体验</a>
    </nav>
    <div class="paper-fallback" aria-hidden="true">
      <img src="/creative-assets/r31-woodblock/washi-final-print-v1.png" alt="">
    </div>
    <header class="print-hero story-state" id="paper-ready" data-state="paper-ready" aria-labelledby="hero-title">
      <div class="hero-copy">
        <p class="eyebrow">一张和纸 · 一次连续套印</p>
        <h1 id="hero-title">让纸记住<br>手的力度</h1>
        <p class="hero-lede">不是三张画面的切换，而是同一张纸在日光、木香和手工压力中逐层留下证据。</p>
        <a class="text-link" href="#pressure-trace">沿着纸面进入工序 <span aria-hidden="true">↓</span></a>
      </div>
      <p class="canvas-note">滚动，观察同一张纸逐层成形</p>
    </header>
    <section class="imprint-journey" aria-label="连续木版套印过程">
      <article class="story-state process-note process-note--pressure" id="pressure-trace" data-state="pressure-trace">
        <span>01 / 03</span><h2>木纹先留下压力</h2><p>湿润的和纸贴合刻版。画面还没有出现，纤维与压痕先记录了手的力度。</p>
      </article>
      <article class="story-state process-note process-note--indigo" id="indigo-layer" data-state="indigo-layer">
        <span>02 / 03</span><h2>靛蓝被纸纤维接住</h2><p>海浪从左向右进入同一坐标。墨色深浅来自施压和吸收，不是另一张图片。</p>
      </article>
      <article class="story-state process-note process-note--vermilion" id="vermilion-register" data-state="vermilion-register">
        <span>03 / 03</span><h2>朱红允许一点错位</h2><p>飞鸟最后落下，微小的套准偏差留在纸上，成为每一张手工作品的签名。</p>
      </article>
    </section>
    <footer class="booking story-state" id="finished-imprint" data-state="finished-imprint" aria-labelledby="booking-title">
      <div>
        <p class="eyebrow">两小时 · 小班制 · 材料齐备</p>
        <h2 id="booking-title">带走一张<br>只属于你的浪</h2>
      </div>
      <div class="booking-action">
        <p>从润纸、上墨到对版，工匠陪你完成每一道工序。无需绘画经验。</p>
        <a class="cta" href="mailto:studio@example.com?subject=预约一次亲手套印">预约一次亲手套印 <span aria-hidden="true">↗</span></a>
      </div>
    </footer>`;
  container.appendChild(page);
  stateNodes = [...page.querySelectorAll<HTMLElement>('[data-state]')];
  return page;
}

function updateExperienceState(progress: number): void {
  if (!root) return;
  const active = states.reduce((best, state) =>
    Math.abs(state.at - progress) < Math.abs(best.at - progress) ? state : best
  );
  root.dataset.activeState = active.id;
  root.style.setProperty('--experience-progress', progress.toFixed(4));
  for (const node of stateNodes) node.classList.toggle('is-active', node.dataset.state === active.id);
}

startExperience(defineExperience({
  mount(context) {
    root = buildPage(context.container);
    root.classList.toggle('is-reduced-motion', context.reducedMotion);
    updateExperienceState(context.reducedMotion ? 1 : 0);
    try {
      scene = createScene(context.canvas, context.viewport.width, context.viewport.height, context.viewport.dpr, context.quality === 'low');
      root.classList.add('webgl-ready');
    } catch {
      context.canvas.style.display = 'none';
      scene = null;
      root.classList.add('webgl-fallback');
    }
  },
  update(frame) {
    const progress = frame.reducedMotion ? 1 : frame.progress;
    updateExperienceState(progress);
    if (!scene) return;
    directScene(scene, progress, frame.pointer.x, frame.pointer.y, frame.elapsed, frame.reducedMotion);
    scene.renderer.render(scene.world, scene.camera);
  },
  resize(viewport) {
    if (scene) scene.resize(viewport.width, viewport.height, viewport.dpr);
  },
  dispose() {
    scene?.dispose();
    scene = null;
    stateNodes = [];
    root?.remove();
    root = null;
  }
}));

import * as THREE from 'three';

export interface PrintScene {
  renderer: THREE.WebGLRenderer;
  world: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  paper: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
  paperMaterial: THREE.ShaderMaterial;
  presses: THREE.Mesh<THREE.BoxGeometry, THREE.MeshStandardMaterial>[];
  shadow: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
  resize(width: number, height: number, dpr: number): void;
  dispose(): void;
}

const vertexShader = `
  varying vec2 vUv;
  varying float vRelief;
  uniform float uRelief;
  uniform float uTime;
  float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
  void main(){
    vUv=uv;
    float fiber=(hash(floor(uv*vec2(90.0,58.0)))-.5)*.008;
    float wave=sin(uv.x*24.0+sin(uv.y*13.0))*uRelief*.012;
    vRelief=wave+fiber;
    vec3 p=position;
    p.z+=vRelief+sin(uv.x*3.14159)*sin(uv.y*3.14159)*.025;
    gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0);
  }`;

const fragmentShader = `
  precision highp float;
  varying vec2 vUv;
  varying float vRelief;
  uniform sampler2D uArtwork;
  uniform float uIndigo;
  uniform float uVermilion;
  uniform float uRelief;
  uniform float uTime;
  uniform vec2 uPointer;
  float hash(vec2 p){ return fract(sin(dot(p,vec2(41.3,289.1)))*45758.5453); }
  void main(){
    vec2 uv=vUv;
    float grain=hash(floor(uv*vec2(260.0,170.0)))*.06;
    float longFiber=sin(uv.x*430.0+sin(uv.y*31.0))*sin(uv.y*260.0)*.018;
    vec3 paper=vec3(.965,.925,.82)+grain+longFiber;
    float deckle=smoothstep(.0,.025,min(min(uv.x,1.0-uv.x),min(uv.y,1.0-uv.y)));
    vec4 artwork=texture2D(uArtwork,uv);
    float artAlpha=smoothstep(.42,.86,artwork.a);
    float high=max(max(artwork.r,artwork.g),artwork.b);
    float low=min(min(artwork.r,artwork.g),artwork.b);
    float luminance=dot(artwork.rgb,vec3(.2126,.7152,.0722));
    float chromaInk=smoothstep(.025,.12,high-low);
    float darkInk=1.0-smoothstep(.48,.82,luminance);
    float inkMask=max(chromaInk,darkInk)*artAlpha;
    float redClass=smoothstep(.015,.11,artwork.r-artwork.b);
    float redMask=inkMask*redClass;
    float blueMask=inkMask*(1.0-redClass);
    float neutralMask=clamp(artAlpha-inkMask,0.0,1.0);
    vec3 color=mix(paper,artwork.rgb,neutralMask*.9);
    float blueSweep=(1.0-smoothstep(uIndigo*1.2-.14,uIndigo*1.2+.14,uv.x))*uIndigo;
    float redSweep=smoothstep(1.12-uVermilion*1.28,1.32-uVermilion*1.28,uv.x)*uVermilion;
    color=mix(color,artwork.rgb,clamp(blueMask*blueSweep+redMask*redSweep,0.0,1.0));
    float sheen=max(0.0,1.0-distance(uv,uPointer*.12+vec2(.5))*.9)*.025;
    color+=sheen+uRelief*vRelief*1.3;
    float printState=max(uIndigo,uVermilion);
    gl_FragColor=vec4(color,mix(deckle,artAlpha,printState));
  }`;

function createWoodTexture(): THREE.CanvasTexture {
  const canvas=document.createElement('canvas');
  canvas.width=512;
  canvas.height=512;
  const context=canvas.getContext('2d');
  if(!context) return new THREE.CanvasTexture(canvas);
  const gradient=context.createLinearGradient(0,0,512,512);
  gradient.addColorStop(0,'#b8753e');
  gradient.addColorStop(.48,'#d49a5e');
  gradient.addColorStop(1,'#a96537');
  context.fillStyle=gradient;
  context.fillRect(0,0,512,512);
  for(let index=0;index<42;index+=1){
    const y=index*13+Math.sin(index*1.7)*7;
    context.beginPath();
    context.moveTo(0,y);
    for(let x=0;x<=512;x+=24) context.lineTo(x,y+Math.sin(x*.035+index)*4);
    context.strokeStyle=index%5===0?'rgba(88,43,20,.16)':'rgba(255,231,184,.09)';
    context.lineWidth=index%5===0?2:1;
    context.stroke();
  }
  const texture=new THREE.CanvasTexture(canvas);
  texture.colorSpace=THREE.SRGBColorSpace;
  texture.wrapS=texture.wrapT=THREE.RepeatWrapping;
  texture.repeat.set(2.6,1.8);
  return texture;
}

export function createScene(canvas: HTMLCanvasElement, width: number, height: number, dpr: number, lowQuality: boolean): PrintScene {
  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: !lowQuality, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(dpr, lowQuality ? 1.25 : 2));
  renderer.setSize(width, height, false);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.shadowMap.enabled = !lowQuality;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const world = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(35, width / Math.max(height, 1), .1, 30);
  camera.position.set(0, 3.8, 4.4);
  camera.lookAt(0, 0, 0);

  const tableTexture=createWoodTexture();
  tableTexture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());
  const tableMaterial = new THREE.MeshStandardMaterial({ color: 0xc58a52, map: tableTexture, roughness: .82, metalness: 0 });
  const table = new THREE.Mesh(new THREE.PlaneGeometry(20, 14), tableMaterial);
  table.rotation.x = -Math.PI / 2;
  table.position.y = -.14;
  world.add(table);

  const artwork=new THREE.TextureLoader().load('/creative-assets/r31-woodblock/washi-final-print-v1.png');
  artwork.colorSpace=THREE.SRGBColorSpace;
  artwork.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());
  const paperMaterial = new THREE.ShaderMaterial({
    vertexShader, fragmentShader, transparent: true, side: THREE.DoubleSide,
    uniforms: {
      uArtwork: { value: artwork }, uIndigo: { value: 0 }, uVermilion: { value: 0 }, uRelief: { value: 0 },
      uTime: { value: 0 }, uPointer: { value: new THREE.Vector2() }
    }
  });
  const paper = new THREE.Mesh(new THREE.PlaneGeometry(3.55, 2.36, lowQuality ? 32 : 72, lowQuality ? 22 : 48), paperMaterial);
  paper.rotation.x = -Math.PI / 2;
  paper.position.y = .18;
  paper.castShadow = !lowQuality;
  world.add(paper);

  const shadowMaterial = new THREE.MeshBasicMaterial({ color: 0x56351f, transparent: true, opacity: .16, depthWrite: false });
  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(3.7, 2.5), shadowMaterial);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -.125;
  world.add(shadow);

  const pressGeometry = new THREE.BoxGeometry(3.35, .09, 2.16);
  const pressColors = [0x9b6339, 0x315979, 0xa84532];
  const presses = pressColors.map((color, index) => {
    const material = new THREE.MeshStandardMaterial({ color, roughness: .86, transparent: true, opacity: 0 });
    const mesh = new THREE.Mesh(pressGeometry, material);
    mesh.position.set(0, 2.6 + index * .18, 0);
    mesh.castShadow = !lowQuality;
    world.add(mesh);
    return mesh;
  });

  world.add(new THREE.HemisphereLight(0xfff5db, 0x8b5735, 2.1));
  const sun = new THREE.DirectionalLight(0xffe3b0, 3.2);
  sun.position.set(-3, 6, 4);
  sun.castShadow = !lowQuality;
  world.add(sun);

  const resize = (nextWidth: number, nextHeight: number, nextDpr: number): void => {
    camera.aspect = nextWidth / Math.max(nextHeight, 1);
    camera.updateProjectionMatrix();
    renderer.setPixelRatio(Math.min(nextDpr, lowQuality ? 1.25 : 2));
    renderer.setSize(nextWidth, nextHeight, false);
  };
  const dispose = (): void => {
    paper.geometry.dispose();
    paperMaterial.dispose();
    shadow.geometry.dispose();
    shadowMaterial.dispose();
    pressGeometry.dispose();
    for (const press of presses) press.material.dispose();
    table.geometry.dispose();
    tableMaterial.dispose();
    tableTexture.dispose();
    artwork.dispose();
    renderer.dispose();
  };
  return { renderer, world, camera, paper, paperMaterial, presses, shadow, resize, dispose };
}

import * as THREE from 'three';
import type { PrintScene } from './scene';

const target = new THREE.Vector3();
const ease = (value: number): number => {
  const x = THREE.MathUtils.clamp(value, 0, 1);
  return x * x * (3 - 2 * x);
};
const windowPulse = (progress: number, center: number, width: number): number =>
  Math.max(0, 1 - Math.abs(progress - center) / width);

export function directScene(scene: PrintScene, progress: number, pointerX: number, pointerY: number, elapsed: number, reducedMotion: boolean): void {
  const p = THREE.MathUtils.clamp(progress, 0, 1);
  const relief = ease((p - .09) / .18);
  const indigo = ease((p - .32) / .22);
  const vermilion = ease((p - .62) / .18);
  scene.paperMaterial.uniforms.uRelief.value = relief;
  scene.paperMaterial.uniforms.uIndigo.value = indigo;
  scene.paperMaterial.uniforms.uVermilion.value = vermilion;
  scene.paperMaterial.uniforms.uTime.value = elapsed;
  scene.paperMaterial.uniforms.uPointer.value.set(pointerX, pointerY);

  const centers = [.2, .46, .72];
  for (let index = 0; index < scene.presses.length; index += 1) {
    const press = scene.presses[index];
    const pulse = windowPulse(p, centers[index], .115);
    press.position.y = .28 + (1 - ease(pulse)) * 2.2;
    press.material.opacity = pulse * .42;
    press.visible = pulse > .015 && !reducedMotion;
  }

  const settle = ease((p - .8) / .16);
  const processFocus = windowPulse(p, .5, .43);
  scene.paper.position.x = -.58 * processFocus;
  scene.paper.position.y = .18 - settle * .045;
  scene.paper.rotation.z = THREE.MathUtils.lerp(-.025, .012, settle);
  scene.shadow.material.opacity = .13 + settle * .1;
  scene.shadow.position.x = scene.paper.position.x;
  for (const press of scene.presses) press.position.x = scene.paper.position.x;

  const side = reducedMotion ? 0 : pointerX * .055;
  scene.camera.position.x = THREE.MathUtils.lerp(-.42, .18, ease(p)) + side;
  scene.camera.position.y = THREE.MathUtils.lerp(3.65, 4.05, settle);
  scene.camera.position.z = THREE.MathUtils.lerp(4.55, 4.05, settle) + pointerY * .03;
  target.set(THREE.MathUtils.lerp(.25, 0, settle), 0, 0);
  scene.camera.lookAt(target);
}

*{box-sizing:border-box}
html{scroll-behavior:smooth;background:#b95f2e}
body{margin:0;max-width:100%;overflow-x:clip;color:#2d271f;background:#b95f2e;font-family:"Noto Serif SC","Songti SC",serif}
body::before{content:"";position:fixed;inset:0;z-index:-2;background:linear-gradient(108deg,rgba(255,213,151,.16),transparent 28% 72%,rgba(112,45,17,.14)),repeating-linear-gradient(176deg,rgba(74,31,15,.16) 0 2px,transparent 2px 96px),linear-gradient(115deg,#bd622e,#d67b3f 56%,#a84e27)}
canvas{position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}
.print-page{--experience-progress:0;position:relative;z-index:1;min-height:420vh}
.print-nav{position:fixed;z-index:5;top:0;left:0;width:100%;display:grid;grid-template-columns:1fr auto 1fr;align-items:start;padding:24px clamp(22px,5vw,76px);font:650 12px/1.3 system-ui,sans-serif;letter-spacing:.13em;pointer-events:none}
.print-nav>a{color:inherit;text-decoration:none;pointer-events:auto}.print-nav>a:last-child{justify-self:end}.print-mark{letter-spacing:.2em}
.state-meter{position:relative;width:190px;height:30px;text-align:center}.state-meter span{position:absolute;inset:0;display:grid;grid-template-columns:auto 1fr;gap:9px;align-items:start;opacity:0;transform:translateY(7px);transition:opacity .3s ease,transform .3s ease}.state-meter span.is-active{opacity:1;transform:none}.state-meter b{font:700 9px/1.5 system-ui,sans-serif;color:#9f2f22}.state-meter span{font:650 11px/1.5 system-ui,sans-serif}
.paper-fallback{display:none;position:fixed;z-index:-1;left:49%;top:49%;width:min(66vw,920px);transform:translate(-50%,-50%) rotate(-1deg);filter:drop-shadow(0 28px 30px rgba(74,43,20,.23))}.paper-fallback img{display:block;width:100%;height:auto}.webgl-fallback .paper-fallback{display:block}
.print-hero{min-height:92vh;padding:17vh clamp(22px,7vw,108px) 8vh;display:flex;align-items:flex-start;position:relative}
.hero-copy{width:min(450px,39vw);padding:22px 0;background:linear-gradient(90deg,rgba(233,194,137,.74),rgba(233,194,137,0));text-shadow:0 1px rgba(255,245,218,.5)}
.eyebrow{margin:0 0 20px;font:700 11px/1.4 system-ui,sans-serif;letter-spacing:.18em;text-transform:uppercase}.hero-copy h1{margin:0;font-size:clamp(44px,6.4vw,90px);line-height:.98;font-weight:500;letter-spacing:-.06em}.hero-lede{max-width:27em;margin:25px 0 22px;font-size:clamp(15px,1.3vw,18px);line-height:1.85}.text-link{color:inherit;font:700 13px/1.4 system-ui,sans-serif;text-decoration:none;border-bottom:1px solid;padding-bottom:7px}.canvas-note{position:absolute;right:clamp(22px,5vw,76px);bottom:4vh;margin:0;font:600 10px/1.4 system-ui,sans-serif;letter-spacing:.12em;writing-mode:vertical-rl}
.imprint-journey{min-height:244vh;padding:10vh clamp(22px,6vw,92px) 18vh}
.process-note{position:fixed;z-index:3;top:50%;right:6vw;width:min(340px,31vw);min-height:42vh;display:flex;flex-direction:column;justify-content:center;padding:24px 26px;background:rgba(239,211,162,.62);border-top:1px solid rgba(45,39,31,.3);box-shadow:0 22px 56px rgba(91,52,25,.08);opacity:0;visibility:hidden;pointer-events:none;transform:translate(22px,-50%);transition:opacity .35s ease,transform .35s ease,background-color .35s ease}.process-note.is-active{opacity:1;visibility:visible;transform:translate(0,-50%);background:rgba(244,218,173,.9)}
.process-note--indigo{width:min(380px,34vw)}.process-note--vermilion{width:min(320px,29vw)}
.process-note span{font:700 10px system-ui,sans-serif;letter-spacing:.14em;color:#923b2a}.process-note h2{font-size:clamp(23px,2.3vw,33px);font-weight:500;line-height:1.25;margin:15px 0}.process-note p,.booking-action p{font-size:15px;line-height:1.85;margin:0}
.booking{position:relative;z-index:2;min-height:84vh;padding:24vh clamp(22px,7vw,108px) 10vh;display:grid;grid-template-columns:1.2fr .8fr;gap:8vw;align-items:end;background:linear-gradient(180deg,transparent 0 22%,rgba(242,220,177,.5) 58%,rgba(242,220,177,.94))}.booking h2{margin:0;font-size:clamp(42px,6vw,86px);line-height:1.04;font-weight:500;letter-spacing:-.05em}.booking-action{max-width:440px}.cta{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-top:32px;padding:18px 20px;background:#b94835;color:#fff9ea;text-decoration:none;font:700 15px/1.4 system-ui,sans-serif;box-shadow:0 8px 24px rgba(89,45,27,.18)}
.story-state{scroll-margin-top:14vh}
.print-page.is-reduced-motion{min-height:auto}.print-page.is-reduced-motion .story-state{opacity:1;visibility:visible;transform:none}.print-page.is-reduced-motion .imprint-journey{min-height:auto;display:grid;gap:4vh}.print-page.is-reduced-motion .process-note{position:relative;top:auto;right:auto;min-height:auto;margin:0 0 0 auto;pointer-events:auto}.print-page.is-reduced-motion .booking{min-height:78vh}
@media(max-width:700px){
  .print-page{min-height:430vh}.print-nav{grid-template-columns:1fr 1fr;padding:20px 18px}.state-meter{display:none}.print-hero{min-height:100svh;padding:11vh 20px 7vh}.hero-copy{width:100%;padding:13px 0;background:linear-gradient(90deg,rgba(222,156,93,.78),rgba(222,156,93,.12))}.hero-copy h1{font-size:clamp(42px,14vw,62px);max-width:7em}.hero-lede{width:79%;margin-top:18px;font-size:14px;line-height:1.7}.canvas-note{right:16px;bottom:4vh}.imprint-journey{min-height:254vh;padding:12vh 18px}.process-note,.process-note--indigo,.process-note--vermilion{right:18px;width:min(86%,340px);min-height:48vh;margin:0;padding:22px 20px;background:rgba(239,211,162,.72)}.process-note.is-active{background:rgba(244,218,173,.93)}.booking{min-height:100svh;padding:30vh 20px 9vh;display:block}.booking h2{font-size:clamp(40px,13vw,62px)}.booking-action{margin-top:8vh}.cta{min-height:58px}.paper-fallback{left:58%;top:59%;width:112vw}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.process-note{transition:none}.state-meter span{transition:none}}
